import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import TagihanIPL from "./TagihanIPL";
import PembayaranIPL from "./PembayaranIPL";
import RekapIPL from "./RekapIPL";
import TransaksiBatalIPL from "./TransaksiBatalIPL";
import { useAuth } from "@/contexts/AuthContext";

export default function IplPage() {
  const { user, token, logout } = useAuth();
  const [refreshKey, setRefreshKey] = useState(0);

  const handlePaymentSuccess = () => {
    setRefreshKey(prev => prev + 1);
  };

  return (
    <div className="p-6 space-y-6">
      {/* HEADER */}
      <div>
        <h1 className="text-3xl font-bold dark:text-gray-100">Iuran IPL</h1>
        <p className="text-sm text-gray-600 dark:text-gray-400">Kelola tagihan dan pembayaran Iuran Pengelolaan Lingkungan KBBS</p>
      </div>

      {/* TABS */}
      <div className="bg-white dark:bg-gray-900 rounded-lg border dark:border-gray-700">
        <Tabs defaultValue="tagihan" className="w-full">
          <TabsList className="w-full justify-start rounded-none border-b dark:border-gray-700 bg-transparent p-0">
            <TabsTrigger 
              value="tagihan"
              className="rounded-none border-b-2 border-transparent px-4 py-3 data-[state=active]:border-cyan-500"
            >
              Tagihan IPL
            </TabsTrigger>
            {/* Hidden: Pembayaran IPL Tab */}
            {/* <TabsTrigger 
              value="pembayaran"
              className="rounded-none border-b-2 border-transparent px-4 py-3 data-[state=active]:border-cyan-500"
            >
              Pembayaran IPL
            </TabsTrigger> */}
            <TabsTrigger 
              value="rekap"
              className="rounded-none border-b-2 border-transparent px-4 py-3 data-[state=active]:border-cyan-500"
            >
              Rekap IPL
            </TabsTrigger>
            <TabsTrigger 
              value="transaksi-batal"
              className="rounded-none border-b-2 border-transparent px-4 py-3 data-[state=active]:border-cyan-500"
            >
              Transaksi Batal
            </TabsTrigger>
          </TabsList>

          {/* TAB 0: TAGIHAN */}
          <TabsContent value="tagihan" className="p-6">
            <TagihanIPL key={refreshKey} />
          </TabsContent>

          {/* TAB 1: PEMBAYARAN */}
          <TabsContent value="pembayaran" className="p-6">
            <PembayaranIPL key={refreshKey} onPaymentSuccess={handlePaymentSuccess} />
          </TabsContent>

          {/* TAB 2: REKAP */}
          <TabsContent value="rekap" className="p-6">
            <RekapIPL />
          </TabsContent>

          {/* TAB 3: TRANSAKSI BATAL */}
          <TabsContent value="transaksi-batal" className="p-6">
            <TransaksiBatalIPL key={refreshKey} />
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}
