import React, { useEffect, useMemo, useState } from 'react';
import axios from 'axios';
import LineChart from '../LineChart';
import DonutChart from '../DonutChart';
import LineComparisonChart from '../LineComparisonChart';
import BarChart from '../BarChart';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue
} from '../ui/select';
import { useAuth } from '../../contexts/AuthContext';

const monthDropdown = [
  { value: '3', label: '3 Bulan' },
  { value: '6', label: '6 Bulan' },
  { value: '12', label: '12 Bulan' }
];

const chartTypeOptions = [
  { value: 'line', label: 'Line' },
  { value: 'bar', label: 'Bar' },
  { value: 'donut', label: 'Donut' }
];

const IplFinancialAnalyticsSection = () => {
  const { token } = useAuth();
  const [incomeTrend, setIncomeTrend] = useState(null);
  const [categoryUsage, setCategoryUsage] = useState(null);
  const [comparisonData, setComparisonData] = useState(null);
  const [trendMonths, setTrendMonths] = useState(12);
  const [comparisonMonths, setComparisonMonths] = useState(6);
  const [comparisonChartType, setComparisonChartType] = useState('line');
  const [trendLoading, setTrendLoading] = useState(false);
  const [categoryLoading, setCategoryLoading] = useState(false);
  const [comparisonLoading, setComparisonLoading] = useState(false);
  const [error, setError] = useState(null);

  const headers = useMemo(() => (token ? { Authorization: `Bearer ${token}` } : {}), [token]);
  const isLoading = trendLoading || categoryLoading || comparisonLoading;

  useEffect(() => {
    if (!token) return;
    const loadTrend = async () => {
      try {
        setTrendLoading(true);
        const response = await axios.get(`/api/ipl-analytics/monthly-income-trend?months=${trendMonths}`, { headers });
        setIncomeTrend(response.data);
        setError(null);
      } catch (err) {
        setError(err?.response?.data?.detail || err.message);
      } finally {
        setTrendLoading(false);
      }
    };
    loadTrend();
  }, [headers, token, trendMonths]);

  useEffect(() => {
    if (!token) return;
    const loadCategoryUsage = async () => {
      try {
        setCategoryLoading(true);
        const response = await axios.get('/api/ipl-analytics/category-usage', { headers });
        setCategoryUsage(response.data);
        setError(null);
      } catch (err) {
        setError(err?.response?.data?.detail || err.message);
      } finally {
        setCategoryLoading(false);
      }
    };
    loadCategoryUsage();
  }, [headers, token]);

  useEffect(() => {
    if (!token) return;
    const loadComparison = async () => {
      try {
        setComparisonLoading(true);
        const response = await axios.get(`/api/ipl-analytics/income-vs-expense?months=${comparisonMonths}`, { headers });
        setComparisonData(response.data);
        setError(null);
      } catch (err) {
        setError(err?.response?.data?.detail || err.message);
      } finally {
        setComparisonLoading(false);
      }
    };
    loadComparison();
  }, [comparisonMonths, headers, token]);

  if (!token) {
    return null;
  }

  return (
    <section className="space-y-6">
     

      {error && !isLoading && (
        <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-md text-sm">
          {error}
        </div>
      )}

      {isLoading && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {[...Array(3)].map((_, idx) => (
            <div key={idx} className="bg-white dark:bg-gray-800 rounded-lg shadow p-6 animate-pulse h-64" />
          ))}
        </div>
      )}

      {!isLoading && incomeTrend && comparisonData && categoryUsage && (
        <>
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <LineChart
              title="Grafik Tren Iuran IPL per Bulan"
              data={incomeTrend.data.map((entry) => ({
                label: entry.label,
                value: entry.value
              }))}
              dropdownOptions={monthDropdown}
              defaultValue="12"
              selectedValue={trendMonths.toString()}
              onDropdownChange={(val) => setTrendMonths(Number(val))}
              value={new Intl.NumberFormat('id-ID', {
                style: 'currency',
                currency: 'IDR',
                minimumFractionDigits: 0
              }).format(incomeTrend.total_income || 0)}
              showValue={true}
            />

            <DonutChart
              title="Grafik Penggunaan Dana IPL per Kategori"
              data={categoryUsage.data.map((entry) => ({
                label: entry.label,
                value: entry.value,
                color: entry.color
              }))}
              totalLabel={`(Total ${new Intl.NumberFormat('id-ID', {
                style: 'currency',
                currency: 'IDR',
                minimumFractionDigits: 0
              }).format(categoryUsage.total_expense || 0)})`}
            />
          </div>

          <div className="bg-white dark:bg-gray-800 rounded-lg shadow">
            <div className="px-6 py-4 border-b border-gray-200 dark:border-gray-700 flex flex-wrap items-center justify-between gap-4">
              <div>
                <p className="text-sm font-medium text-gray-700 dark:text-gray-200">
                  Grafik Pemasukan vs Pengeluaran
                </p>
                <p className="text-xs text-gray-500">
                  Pilih tipe visualisasi yang diinginkan.
                </p>
              </div>
              <div className="flex flex-wrap gap-2">
                <Select
                  value={comparisonMonths.toString()}
                  onValueChange={(val) => setComparisonMonths(Number(val))}
                >
                  <SelectTrigger className="w-32 h-8 text-xs">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {monthDropdown.map((option) => (
                      <SelectItem key={option.value} value={option.value}>
                        {option.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>

                <Select
                  value={comparisonChartType}
                  onValueChange={setComparisonChartType}
                >
                  <SelectTrigger className="w-32 h-8 text-xs">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {chartTypeOptions.map((option) => (
                      <SelectItem key={option.value} value={option.value}>
                        {option.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="p-6">
              {comparisonChartType === 'line' && (
                <LineComparisonChart
                  title="Grafik Pemasukan vs Pengeluaran"
                  data={comparisonData.data}
                  frameless
                />
              )}

              {comparisonChartType === 'bar' && (
                <BarChart
                  title="Grafik Pemasukan vs Pengeluaran"
                  data={comparisonData.data}
                  frameless
                />
              )}

              {comparisonChartType === 'donut' && (
                <DonutChart
                  title="Pemasukan vs Pengeluaran"
                  data={[
                    {
                      label: 'Total Pemasukan',
                      value: comparisonData.totals?.pemasukan || 0,
                      color: '#10b981'
                    },
                    {
                      label: 'Total Pengeluaran',
                      value: comparisonData.totals?.pengeluaran || 0,
                      color: '#ef4444'
                    }
                  ]}
                  totalLabel={`(${new Intl.NumberFormat('id-ID', {
                    style: 'currency',
                    currency: 'IDR',
                    minimumFractionDigits: 0
                  }).format((comparisonData.totals?.pemasukan || 0) + (comparisonData.totals?.pengeluaran || 0))})`}
                  frameless
                />
              )}
            </div>
          </div>
        </>
      )}
    </section>
  );
};

export default IplFinancialAnalyticsSection;
