import { useEffect, useState } from "react";

import { API_BASE_URL } from '@/config/api';
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "@/components/ui/sonner";
import { useAuth } from "@/contexts/AuthContext";
import {
  MENU_ITEMS,
  PERMISSIONS_MATRIX,
  CRUD_ACTIONS,
} from "@/lib/permissionsMatrix";
import { Checkbox } from "@/components/ui/checkbox";
import { AlertCircle, Check, X } from "lucide-react";

export default function UserPermissionsPage() {
  const { token, user } = useAuth();
  const [permissions, setPermissions] = useState({});
  const [roles, setRoles] = useState(['admin']);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);

  // Load roles and permissions on mount
  useEffect(() => {
    if (token) {
      loadRolesAndPermissions();
    }
  }, [token]);

  // Load all available roles (admin + custom roles only)
  const loadRolesAndPermissions = async () => {
    try {
      setLoading(true);
      
      // First, load roles
      const rolesResponse = await fetch(`${API_BASE_URL}/api/roles`, {
        headers: {
          'Authorization': `Bearer ${token}`,
        },
      });

      let roleNames = ['admin'];
      if (rolesResponse.ok) {
        const rolesData = await rolesResponse.json();
        roleNames = rolesData.map(r => r.name).sort((a, b) => {
          if (a === 'admin') return -1;
          if (b === 'admin') return 1;
          return a.localeCompare(b);
        });
        console.log('📋 Loaded roles:', roleNames);
        setRoles(roleNames);
      }

      // Then load permissions for those roles
      const initialPerms = {};
      for (const role of roleNames) {
        try {
          const response = await fetch(`${API_BASE_URL}/api/role-permissions/${role}`, {
            headers: {
              'Authorization': `Bearer ${token}`,
            },
          });
          
          if (response.ok) {
            const data = await response.json();
            // Use saved permissions if available, otherwise use defaults
            initialPerms[role] = data.permissions && Object.keys(data.permissions).length > 0 
              ? data.permissions 
              : { ...PERMISSIONS_MATRIX[role] || getDefaultPermissionsForRole(role) };
          } else {
            // Fallback to defaults
            initialPerms[role] = PERMISSIONS_MATRIX[role] || getDefaultPermissionsForRole(role);
          }
        } catch (error) {
          console.warn(`Could not load permissions for ${role}, using defaults:`, error);
          initialPerms[role] = PERMISSIONS_MATRIX[role] || getDefaultPermissionsForRole(role);
        }
      }
      
      console.log('✅ Permissions loaded:', Object.keys(initialPerms));
      setPermissions(initialPerms);
    } catch (error) {
      console.error('Error loading permissions:', error);
      toast.error('Gagal memuat permissions');
    } finally {
      setLoading(false);
    }
  };

  // Get default permissions structure for a role
  const getDefaultPermissionsForRole = (role) => {
    const perms = {};
    MENU_ITEMS.forEach(menu => {
      perms[menu.id] = {
        read: false,
        create: false,
        update: false,
        delete: false,
      };
      // Admin gets all permissions by default
      if (role === 'admin') {
        perms[menu.id] = {
          read: true,
          create: true,
          update: true,
          delete: true,
        };
      }
    });
    return perms;
  };

  const handleTogglePermission = async (role, menuId, action) => {
    try {
      setSaving(true);
      
      // Ensure the menu object exists for this role
      if (!permissions[role][menuId]) {
        permissions[role][menuId] = {
          read: false,
          create: false,
          update: false,
          delete: false,
        };
      }
      
      // Create updated permissions
      const updatedPermissions = {
        ...permissions,
        [role]: {
          ...permissions[role],
          [menuId]: {
            ...permissions[role][menuId],
            [action]: !permissions[role][menuId][action],
          },
        },
      };

      // Update local state immediately
      setPermissions(updatedPermissions);
      
      console.log(`💾 Saving permission: ${role} > ${menuId} > ${action}`);
      console.log(`📊 Full permissions to save:`, updatedPermissions[role]);
      console.log(`🔐 Token: ${token ? 'Present' : 'Missing'}`);

      // Save to database
      const response = await fetch(`${API_BASE_URL}/api/role-permissions/${role}`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`,
        },
        body: JSON.stringify({
          role,
          permissions: updatedPermissions[role],
        }),
      });

      console.log(`🌐 API Response status: ${response.status}`);

      let result;
      try {
        result = await response.json();
      } catch (e) {
        console.error('Failed to parse response:', e);
        throw new Error(`Invalid response from server: ${response.status}`);
      }

      if (!response.ok) {
        console.error('API Error:', result);
        throw new Error(`Failed to save permissions: ${response.status}`);
      }

      console.log(`✅ Saved successfully:`, result);
      toast.success(`Permission ${action} untuk ${menuId} disimpan`);
    } catch (error) {
      console.error('❌ Error saving permission:', error);
      toast.error('Gagal menyimpan permission: ' + error.message);
      // Revert on error
      loadRolesAndPermissions();
    } finally {
      setSaving(false);
    }
  };

  // Toggle all permissions for a specific role and action across all menus
  const handleToggleAllForAction = async (role, action, newValue) => {
    try {
      setSaving(true);
      
      const updatedPerms = { ...permissions[role] };
      MENU_ITEMS.forEach(menu => {
        // Ensure menu object exists before trying to update it
        if (!updatedPerms[menu.id]) {
          updatedPerms[menu.id] = {
            read: false,
            create: false,
            update: false,
            delete: false,
          };
        }
        updatedPerms[menu.id] = {
          ...updatedPerms[menu.id],
          [action]: newValue,
        };
      });

      // Update local state
      setPermissions((prev) => ({
        ...prev,
        [role]: updatedPerms,
      }));

      // Save to database
      const response = await fetch(`${API_BASE_URL}/api/role-permissions/${role}`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`,
        },
        body: JSON.stringify({
          role,
          permissions: updatedPerms,
        }),
      });

      if (!response.ok) {
        throw new Error('Failed to save permissions');
      }

      toast.success(`${action.toUpperCase()} untuk semua menu pada role ${role} ${newValue ? 'diaktifkan' : 'dinonaktifkan'}`);
    } catch (error) {
      console.error('Error saving permissions:', error);
      toast.error('Gagal menyimpan permissions');
      loadRolesAndPermissions();
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-screen">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500 mx-auto mb-4"></div>
          <p className="text-gray-500">Memuat permissions...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-4 p-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-800 dark:text-white mb-1">
            Matriks Hak Akses per Role
          </h1>
          <p className="text-sm text-gray-500 dark:text-gray-400">
            Kelola hak akses untuk setiap role dengan meng-klik checkbox
          </p>
        </div>
      </div>

      {/* Legend */}
      <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg p-4 flex items-start gap-3">
        <AlertCircle className="w-5 h-5 text-blue-600 dark:text-blue-400 flex-shrink-0 mt-0.5" />
        <div className="text-sm text-blue-700 dark:text-blue-300">
          <strong>Keterangan:</strong> B = Baca (Read) | T = Tambah (Create) | E = Edit (Update) | H = Hapus (Delete)
          <br />
          Klik checkbox untuk mengubah permission, perubahan akan tersimpan otomatis ke database
        </div>
      </div>

     

      {/* Permissions Matrix Table */}
      <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-lg overflow-x-auto">
        <table className="w-full border-collapse">
          <thead className="bg-gray-50 dark:bg-gray-800">
            <tr>
              <th className="sticky left-0 z-10 bg-gray-50 dark:bg-gray-800 w-32 min-w-[200px] text-left p-3 font-semibold text-gray-700 dark:text-gray-300 border-r border-gray-200 dark:border-gray-700">
                Menu
              </th>
              {roles.map((role) => (
                <th key={role} colSpan={4} className="text-center border-l border-gray-200 dark:border-gray-700">
                  <div className="capitalize font-bold text-base text-blue-600 dark:text-blue-400 py-2">
                    {role.toUpperCase()}
                  </div>
                </th>
              ))}
            </tr>
            <tr>
              <th className="sticky left-0 z-10 bg-gray-50 dark:bg-gray-800"></th>
              {roles.map((role) =>
                CRUD_ACTIONS.map((action) => {
                  // Check if all menus have this permission
                  const allChecked = MENU_ITEMS.every(menu => 
                    permissions[role]?.[menu.id]?.[action] === true
                  );
                  const someChecked = MENU_ITEMS.some(menu => 
                    permissions[role]?.[menu.id]?.[action] === true
                  );
                  const isAdmin = role === 'admin';
                  
                  return (
                    <th
                      key={`${role}-${action}`}
                      className="text-center text-xs font-semibold text-gray-600 dark:text-gray-400 py-2 px-1 border-l border-gray-200 dark:border-gray-700"
                    >
                      <div className="flex flex-col items-center gap-1">
                        <div className="font-bold">
                          {action === 'read' && 'B'}
                          {action === 'create' && 'T'}
                          {action === 'update' && 'E'}
                          {action === 'delete' && 'H'}
                        </div>
                        {/* Select All checkbox - disabled untuk admin role */}
                        {role !== 'admin' && (
                          <input
                            type="checkbox"
                            checked={allChecked}
                            ref={el => {
                              if (el && someChecked && !allChecked) {
                                el.indeterminate = true;
                              }
                            }}
                            onChange={(e) => handleToggleAllForAction(role, action, e.target.checked)}
                            className="cursor-pointer w-3 h-3"
                            title="Select All"
                          />
                        )}
                      </div>
                    </th>
                  );
                })
              )}
            </tr>
          </thead>
          <tbody>
            {MENU_ITEMS.map((menu) => (
              <tr key={menu.id} className="hover:bg-gray-50 dark:hover:bg-gray-800 border-b border-gray-200 dark:border-gray-700">
                <td className="sticky left-0 z-10 bg-white dark:bg-gray-900 font-medium text-gray-700 dark:text-gray-300 w-32 min-w-[200px] p-3 border-r border-gray-200 dark:border-gray-700">
                  {menu.label}
                </td>
                {roles.map((role) =>
                  CRUD_ACTIONS.map((action) => {
                    const hasPermission =
                      permissions[role]?.[menu.id]?.[action] === true;
                    // Admin role harus selalu readonly - tidak bisa diubah
                    const isDisabled = role === 'admin';
                    
                    return (
                      <td
                        key={`${role}-${menu.id}-${action}`}
                        className="text-center p-2 border-l border-gray-200 dark:border-gray-700"
                      >
                        <div
                          className={`flex items-center justify-center w-8 h-8 rounded transition-all mx-auto ${
                            isDisabled 
                              ? 'cursor-not-allowed opacity-50'
                              : 'cursor-pointer'
                          } ${
                            hasPermission
                              ? 'bg-green-100 dark:bg-green-900/30 hover:bg-green-200 dark:hover:bg-green-900/50'
                              : 'bg-red-100 dark:bg-red-900/30 hover:bg-red-200 dark:hover:bg-red-900/50'
                          }`}
                          onClick={() =>
                            !saving &&
                            !isDisabled &&
                            handleTogglePermission(role, menu.id, action)
                          }
                          title={isDisabled ? `Admin role tidak bisa diubah` : `${action} untuk ${menu.label} role ${role}`}
                        >
                          {hasPermission ? (
                            <Check className="w-4 h-4 text-green-600 dark:text-green-400" />
                          ) : (
                            <X className="w-4 h-4 text-red-600 dark:text-red-400" />
                          )}
                        </div>
                      </td>
                    );
                  })
                )}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Info Box */}
      <div className="bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 rounded-lg p-4">
        <p className="text-sm text-amber-700 dark:text-amber-300">
          <strong>⚠️ Catatan:</strong> Perubahan permissions diterapkan otomatis ketika checkbox diklik. 
          Pastikan Anda telah login dengan akun admin untuk mengubah permissions.
        </p>
      </div>

      {/* Role Descriptions */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg p-4">
          <h3 className="font-semibold text-blue-900 dark:text-blue-300 mb-2">🔐 Admin</h3>
          <p className="text-sm text-blue-700 dark:text-blue-400">
            Memiliki akses penuh ke semua menu dengan izin Create, Read, Update, dan Delete pada semua modul.
          </p>
        </div>
        <div className="bg-purple-50 dark:bg-purple-900/20 border border-purple-200 dark:border-purple-800 rounded-lg p-4">
          <h3 className="font-semibold text-purple-900 dark:text-purple-300 mb-2">👥 Warga</h3>
          <p className="text-sm text-purple-700 dark:text-purple-400">
            Dapat membaca sebagian besar menu tetapi tidak dapat membuat, mengedit, atau menghapus data (Read-only).
          </p>
        </div>
        <div className="bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-800 rounded-lg p-4">
          <h3 className="font-semibold text-green-900 dark:text-green-300 mb-2">💼 Karyawan</h3>
          <p className="text-sm text-green-700 dark:text-green-400">
            Hanya dapat mengakses Dashboard dan Daftar Pengguna dengan izin Read-only.
          </p>
        </div>
      </div>
    </div>
  );
}
