import { useEffect, useState } from "react";

import { API_BASE_URL } from "@/config/api";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  AlertDialog,
  AlertDialogContent,
  AlertDialogHeader,
  AlertDialogFooter,
  AlertDialogTitle,
  AlertDialogCancel,
  AlertDialogAction,
  AlertDialogDescription,
} from "@/components/ui/alert-dialog";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { useAuth } from "@/contexts/AuthContext";
import { toast } from "@/components/ui/sonner";
import { useRolePermissions } from "@/hooks/useRolePermissions";
import { Pencil, Trash2, Filter, X, DollarSign, ImagePlus, Image, Gallery } from "lucide-react";

export default function BiayaRutinPage() {
  const [recurring, setRecurring] = useState([]);
  const [categories, setCategories] = useState([]);
  const [search, setSearch] = useState("");
  const { token, user, logout } = useAuth();
  const { canCreate, canEdit, canDelete } = useRolePermissions(user?.role, token);

  // FORM DIALOG
  const [openForm, setOpenForm] = useState(false);
  const [formData, setFormData] = useState({
    id: null,
    kategori_id: "",
    nama: "",
    deskripsi: "",
    nominal: "",
    periode: "Bulanan",
    aktif: true,
  });

  // DELETE DIALOG
  const [openDelete, setOpenDelete] = useState(false);
  const [deleteId, setDeleteId] = useState(null);
  const [openDeleteImage, setOpenDeleteImage] = useState(false);
  const [deleteImageId, setDeleteImageId] = useState(null);

  // GENERATE DIALOG
  const [openGenerate, setOpenGenerate] = useState(false);
  const [generateResult, setGenerateResult] = useState(null);

  // FILTER
  const [showFilter, setShowFilter] = useState(false);
  const [filterKategori, setFilterKategori] = useState("all");

  // PAGINATION
  const [page, setPage] = useState(1);
  const [perPage, setPerPage] = useState(25);

  // UPLOAD IMAGE
  const [openUploadImage, setOpenUploadImage] = useState(false);
  const [selectedBiayaId, setSelectedBiayaId] = useState(null);
  const [uploadingImages, setUploadingImages] = useState([]);
  const [imagePreview, setImagePreview] = useState([]);

  // IMAGE GALLERY
  const [biayaImages, setBiayaImages] = useState({});  // {biaya_id: [images]}
  const [openGalleryModal, setOpenGalleryModal] = useState(false);
  const [galleryImages, setGalleryImages] = useState([]);
  const [selectedGalleryIndex, setSelectedGalleryIndex] = useState(0);
  const [galleryImageDataUrls, setGalleryImageDataUrls] = useState({});  // {image_id: data_url}

  // LOAD DATA
  const loadRecurring = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/finance-recurring`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.status === 401) {
        logout();
        return;
      }

      const data = await res.json();
      setRecurring(data);
      
      // Load images untuk setiap biaya
      const imagesMap = {};
      for (const biaya of data) {
        try {
          const imgRes = await fetch(`${API_BASE_URL}/api/finance-recurring/${biaya.id}/images`, {
            headers: {
              Authorization: `Bearer ${token}`,
            },
          });
          if (imgRes.ok) {
            const imgData = await imgRes.json();
            imagesMap[biaya.id] = imgData.images || [];
          }
        } catch (err) {
          console.warn(`Failed to load images for biaya ${biaya.id}:`, err);
        }
      }
      setBiayaImages(imagesMap);
    } catch (err) {
      console.error("Gagal load biaya rutin", err);
      toast.error("Gagal memuat data biaya rutin");
    }
  };

  const loadCategories = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/finance-category`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.ok) {
        const data = await res.json();
        setCategories(data);
      }
    } catch (err) {
      console.error("Gagal load kategori", err);
    }
  };

  useEffect(() => {
    loadRecurring();
    loadCategories();
  }, []);

  // FILTER LOGIC
  const filtered = recurring
    .filter((r) => r.nama.toLowerCase().includes(search.toLowerCase()))
    .filter((r) => {
      if (filterKategori === "all") return true;
      return r.kategori_id === filterKategori;
    });

  // PAGINATION
  const totalPages = Math.ceil(filtered.length / perPage);
  const paginatedData = filtered.slice((page - 1) * perPage, page * perPage);

  // HANDLE SAVE
  const handleSave = async () => {
    if (!formData.nama || !formData.kategori_id || !formData.nominal) {
      toast.error("Nama, Kategori, dan Nominal harus diisi");
      return;
    }

    try {
      const url = formData.id
        ? `${API_BASE_URL}/api/finance-recurring/${formData.id}`
        : `${API_BASE_URL}/api/finance-recurring`;

      const method = formData.id ? "PUT" : "POST";

      const res = await fetch(url, {
        method,
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          kategori_id: formData.kategori_id,
          nama: formData.nama,
          deskripsi: formData.deskripsi,
          nominal: parseFloat(formData.nominal),
          periode: formData.periode,
          aktif: formData.aktif,
        }),
      });

      if (res.ok) {
        toast.success(`Biaya rutin berhasil ${formData.id ? "diupdate" : "ditambahkan"}`);
        loadRecurring();
        setOpenForm(false);
        resetForm();
      } else {
        const error = await res.json();
        toast.error(error.detail || "Gagal menyimpan biaya rutin");
      }
    } catch (err) {
      console.error("Error:", err);
      toast.error("Terjadi kesalahan saat menyimpan");
    }
  };

  // HANDLE DELETE
  const handleDelete = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/finance-recurring/${deleteId}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.ok) {
        toast.success("Biaya rutin berhasil dihapus");
        loadRecurring();
      } else {
        const error = await res.json();
        toast.error(error.detail || "Gagal menghapus biaya rutin");
      }
    } catch (err) {
      console.error("Error:", err);
      toast.error("Terjadi kesalahan saat menghapus");
    } finally {
      setOpenDelete(false);
      setDeleteId(null);
    }
  };

  // HANDLE GENERATE
  const handleGenerate = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/finance-recurring/generate-monthly`, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.ok) {
        const result = await res.json();
        setGenerateResult(result);
        toast.success(result.message);
      } else {
        const error = await res.json();
        toast.error(error.detail || "Gagal generate biaya bulanan");
      }
    } catch (err) {
      console.error("Error:", err);
      toast.error("Terjadi kesalahan saat generate biaya");
    }
  };

  const resetForm = () => {
    setFormData({
      id: null,
      kategori_id: "",
      nama: "",
      deskripsi: "",
      nominal: "",
      periode: "Bulanan",
      aktif: true,
    });
  };

  const openEditForm = (item) => {
    setFormData({
      id: item.id,
      kategori_id: item.kategori_id,
      nama: item.nama,
      deskripsi: item.deskripsi || "",
      nominal: item.nominal.toString(),
      periode: item.periode,
      aktif: item.aktif,
    });
    setOpenForm(true);
  };

  const openDeleteDialog = (id) => {
    setDeleteId(id);
    setOpenDelete(true);
  };

  const openUploadImageDialog = (biayaId) => {
    setSelectedBiayaId(biayaId);
    setUploadingImages([]);
    setImagePreview([]);
    setOpenUploadImage(true);
  };

  const handleImageChange = (e) => {
    const files = Array.from(e.target.files || []);
    
    files.forEach((file) => {
      const reader = new FileReader();
      reader.onload = (event) => {
        setImagePreview((prev) => [...prev, {
          id: Date.now() + Math.random(),
          file: file,
          preview: event.target.result
        }]);
      };
      reader.readAsDataURL(file);
    });
    
    // Reset input
    e.target.value = '';
  };

  const removeImagePreview = (id) => {
    setImagePreview((prev) => prev.filter((img) => img.id !== id));
  };

  const handleUploadImages = async () => {
    if (imagePreview.length === 0) {
      toast.error("Pilih minimal 1 gambar");
      return;
    }

    setUploadingImages(imagePreview.map((img) => img.id));

    try {
      const formData = new FormData();
      
      // Append all files to FormData (backend expect "files" field)
      imagePreview.forEach((imgItem) => {
        formData.append('files', imgItem.file);
      });

      const res = await fetch(`${API_BASE_URL}/api/finance-recurring/${selectedBiayaId}/upload-image`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`,
        },
        body: formData,
      });

      // Check status BEFORE parsing JSON
      if (!res.ok) {
        let errorMsg = 'Gagal upload gambar';
        try {
          const errorData = await res.json();
          errorMsg = errorData.detail || errorMsg;
        } catch (e) {
          // Response body mungkin bukan JSON
        }
        throw new Error(errorMsg);
      }

      // Parse JSON hanya jika response OK
      const responseData = await res.json();

      toast.success(`${imagePreview.length} gambar berhasil diupload`);
      setOpenUploadImage(false);
      setImagePreview([]);
      
      // Reload images untuk biaya ini
      try {
        const imgRes = await fetch(`${API_BASE_URL}/api/finance-recurring/${selectedBiayaId}/images`, {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });
        if (imgRes.ok) {
          const imgData = await imgRes.json();
          setBiayaImages((prev) => ({
            ...prev,
            [selectedBiayaId]: imgData.images || []
          }));
        }
      } catch (err) {
        console.warn('Failed to reload images:', err);
      }
    } catch (error) {
      console.error('Error uploading images:', error);
      toast.error(error.message || 'Gagal upload gambar');
    } finally {
      setUploadingImages([]);
    }
  };

  const openImageGalleryModal = (biayaId) => {
    const images = biayaImages[biayaId] || [];
    if (images.length === 0) {
      toast.error("Tidak ada gambar untuk biaya ini");
      return;
    }
    setGalleryImages(images);
    setSelectedGalleryIndex(0);
    setGalleryImageDataUrls({});  // Reset image data URLs
    setOpenGalleryModal(true);

    // Fetch all images as blobs dan convert to data URLs
    const loadImages = async () => {
      const dataUrls = {};
      for (const img of images) {
        try {
          const imgRes = await fetch(
            `${API_BASE_URL}/api/finance-recurring/${biayaId}/images/${img.id}`,
            {
              headers: {
                Authorization: `Bearer ${token}`,
              },
            }
          );

          if (imgRes.ok) {
            const blob = await imgRes.blob();
            const dataUrl = URL.createObjectURL(blob);
            dataUrls[img.id] = dataUrl;
          }
        } catch (err) {
          console.warn(`Failed to load image ${img.id}:`, err);
        }
      }
      setGalleryImageDataUrls(dataUrls);
    };

    loadImages();
  };

  const handleDeleteImage = (imageId) => {
    if (!galleryImages || galleryImages.length === 0) {
      toast.error("Tidak ada gambar yang dipilih");
      return;
    }
    
    const currentImage = galleryImages[selectedGalleryIndex];
    if (!currentImage) {
      toast.error("Gambar tidak ditemukan");
      return;
    }

    const biayaId = currentImage?.biaya_rutin_id;
    if (!biayaId) {
      toast.error("ID biaya tidak ditemukan");
      return;
    }
    
    setDeleteImageId({
      imageId: imageId,
      biayaId: biayaId
    });
    setOpenDeleteImage(true);
  };

  const confirmDeleteImage = async () => {
    if (!deleteImageId) {
      toast.error("Data gambar tidak lengkap");
      return;
    }

    const imageId = deleteImageId.imageId;
    const biayaId = deleteImageId.biayaId;

    if (!imageId || !biayaId) {
      toast.error("Data gambar tidak lengkap (ID missing)");
      return;
    }

    try {
      const res = await fetch(
        `${API_BASE_URL}/api/finance-recurring/${biayaId}/images/${imageId}`,
        {
          method: "DELETE",
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      let errorMsg = "Gagal menghapus foto";
      
      if (!res.ok) {
        try {
          const errorData = await res.json();
          errorMsg = errorData.detail || errorMsg;
        } catch (e) {
          // Response bukan JSON, gunakan status text
          errorMsg = res.statusText || errorMsg;
        }
        throw new Error(errorMsg);
      }

      // Remove image from galleryImages
      const updatedImages = galleryImages.filter((img) => img.id !== imageId);
      
      // Remove image data URL
      const updatedDataUrls = { ...galleryImageDataUrls };
      delete updatedDataUrls[imageId];
      setGalleryImageDataUrls(updatedDataUrls);

      // Update gallery state
      setGalleryImages(updatedImages);

      // Update biayaImages
      setBiayaImages((prev) => ({
        ...prev,
        [biayaId]: prev[biayaId].filter((img) => img.id !== imageId),
      }));

      // Adjust selected index if needed
      if (updatedImages.length === 0) {
        setOpenGalleryModal(false);
      } else if (selectedGalleryIndex >= updatedImages.length) {
        setSelectedGalleryIndex(updatedImages.length - 1);
      }

      toast.success("Foto berhasil dihapus");
      setOpenDeleteImage(false);
      setDeleteImageId(null);
    } catch (error) {
      console.error("Error deleting image:", error);
      toast.error(error.message || "Gagal menghapus foto");
      setOpenDeleteImage(false);
      setDeleteImageId(null);
    }
  };

  const formatRupiah = (val) => {
    return new Intl.NumberFormat("id-ID", {
      style: "currency",
      currency: "IDR",
      minimumFractionDigits: 0,
    }).format(val);
  };

  const handleNominalChange = (e) => {
    // Remove all non-digit characters
    const value = e.target.value.replace(/\D/g, '');
    setFormData({ ...formData, nominal: value });
  };

  const displayNominal = () => {
    if (!formData.nominal) return '';
    return new Intl.NumberFormat("id-ID").format(formData.nominal);
  };

  return (
    <div className="p-6 space-y-6">
      {/* HEADER */}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold dark:text-gray-100">Biaya Rutin</h1>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            Kelola biaya rutin bulanan dan tahunan
          </p>
        </div>
        <div className="flex gap-2">
          {canCreate("biaya-rutin") && (
            <>
              <Button
                onClick={() => setOpenGenerate(true)}
                className="bg-green-500 hover:bg-green-600 text-white gap-2"
              >
                <DollarSign className="h-4 w-4" />
                Generate Biaya Bulanan
              </Button>
              <Button
                onClick={() => {
                  resetForm();
                  setOpenForm(true);
                }}
                className="bg-cyan-500 hover:bg-cyan-600 text-white"
              >
                + Tambah Biaya Rutin
              </Button>
            </>
          )}
        </div>
      </div>

      {/* TOTAL NOMINAL CARD */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-gray-600 dark:text-gray-400">
              Total Nominal Biaya Rutin (Aktif)
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">
              {formatRupiah(recurring.reduce((sum, item) => (item.aktif ? sum + (item.nominal || 0) : sum), 0))}
            </div>
            <p className="text-xs text-gray-500 mt-1">
              {recurring.filter(item => item.aktif).length} dari {recurring.length} item aktif
            </p>
          </CardContent>
        </Card>
      </div>

      {/* SEARCH & FILTER */}
      <div className="bg-white dark:bg-gray-900 p-4 rounded-lg border dark:border-gray-700 space-y-3">
        <div className="flex gap-3 items-center">
          <Input
            placeholder="Cari nama biaya..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="max-w-sm"
          />
          <Button
            variant="outline"
            onClick={() => setShowFilter(!showFilter)}
            className="gap-2"
          >
            <Filter className="h-4 w-4" />
            Filter
          </Button>
        </div>

        {showFilter && (
          <div className="flex gap-3 items-center pt-2 border-t dark:border-gray-700">
            <Label className="text-sm">Kategori:</Label>
            <Select value={filterKategori} onValueChange={setFilterKategori}>
              <SelectTrigger className="w-64">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Semua Kategori</SelectItem>
                {categories.map((cat) => (
                  <SelectItem key={cat.id} value={cat.id}>
                    {cat.nama}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            {filterKategori !== "all" && (
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setFilterKategori("all")}
                className="gap-1"
              >
                <X className="h-4 w-4" />
                Reset
              </Button>
            )}
          </div>
        )}
      </div>

      {/* TABLE */}
      <div className="bg-white dark:bg-gray-900 rounded-lg border dark:border-gray-700">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Nama Biaya</TableHead>
              <TableHead>Kategori</TableHead>
              <TableHead className="text-right">Nominal</TableHead>
              <TableHead>Periode</TableHead>
              <TableHead>Status</TableHead>
              <TableHead className="text-right">Aksi</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {paginatedData.length === 0 ? (
              <TableRow>
                <TableCell colSpan={6} className="text-center text-gray-500">
                  Tidak ada data biaya rutin
                </TableCell>
              </TableRow>
            ) : (
              paginatedData.map((item) => (
                <TableRow key={item.id}>
                  <TableCell>
                    <div>
                      <p className="font-medium">{item.nama}</p>
                      {item.deskripsi && (
                        <p className="text-xs text-gray-500">{item.deskripsi}</p>
                      )}
                    </div>
                  </TableCell>
                  <TableCell>
                    <span className="text-sm">{item.kategori_nama}</span>
                  </TableCell>
                  <TableCell className="text-right font-medium">
                    {formatRupiah(item.nominal)}
                  </TableCell>
                  <TableCell>
                    <span className="px-2 py-1 rounded text-xs font-semibold bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300">
                      {item.periode}
                    </span>
                  </TableCell>
                  <TableCell>
                    <span
                      className={`px-2 py-1 rounded text-xs font-semibold ${
                        item.aktif
                          ? "bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-300"
                          : "bg-gray-100 text-gray-700 dark:bg-gray-700 dark:text-gray-300"
                      }`}
                    >
                      {item.aktif ? "Aktif" : "Nonaktif"}
                    </span>
                  </TableCell>
                  <TableCell className="text-right space-x-2">
                    {canEdit("biaya-rutin") && (
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => openEditForm(item)}
                      >
                        <Pencil className="h-4 w-4" />
                      </Button>
                    )}
                    {canEdit("biaya-rutin") && (
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => openUploadImageDialog(item.id)}
                        title="Upload foto nota bila ada"
                      >
                        <ImagePlus className="h-4 w-4 text-blue-500" />
                      </Button>
                    )}
                    {(biayaImages[item.id]?.length ?? 0) > 0 && (
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => openImageGalleryModal(item.id)}
                        className="relative"
                        title="Lihat galeri foto"
                      >
                        <Image className="h-4 w-4 text-green-500" />
                        <span className="absolute -top-2 -right-2 bg-green-500 text-white text-xs rounded-full w-5 h-5 flex items-center justify-center font-bold">
                          {biayaImages[item.id].length}
                        </span>
                      </Button>
                    )}
                    {canDelete("biaya-rutin") && (
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => openDeleteDialog(item.id)}
                      >
                        <Trash2 className="h-4 w-4 text-red-500" />
                      </Button>
                    )}
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>

        {/* PAGINATION */}
        {totalPages > 1 && (
          <div className="p-4 border-t dark:border-gray-700 flex justify-between items-center">
            <p className="text-sm text-gray-600 dark:text-gray-400">
              Halaman {page} dari {totalPages} ({filtered.length} total)
            </p>
            <div className="flex gap-2">
              <Button
                variant="outline"
                size="sm"
                disabled={page === 1}
                onClick={() => setPage(page - 1)}
              >
                Previous
              </Button>
              <Button
                variant="outline"
                size="sm"
                disabled={page === totalPages}
                onClick={() => setPage(page + 1)}
              >
                Next
              </Button>
            </div>
          </div>
        )}
      </div>

      {/* FORM DIALOG */}
      <Dialog open={openForm} onOpenChange={setOpenForm}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>
              {formData.id ? "Edit Biaya Rutin" : "Tambah Biaya Rutin"}
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <Label htmlFor="nama">Nama Biaya</Label>
              <Input
                id="nama"
                value={formData.nama}
                onChange={(e) => setFormData({ ...formData, nama: e.target.value })}
                placeholder="Contoh: Gaji Security Bulanan"
              />
            </div>
            <div>
              <Label htmlFor="kategori">Kategori</Label>
              <Select
                value={formData.kategori_id}
                onValueChange={(value) => setFormData({ ...formData, kategori_id: value })}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Pilih kategori" />
                </SelectTrigger>
                <SelectContent>
                  {categories.map((cat) => (
                    <SelectItem key={cat.id} value={cat.id}>
                      {cat.nama} ({cat.tipe})
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label htmlFor="deskripsi">Deskripsi (Opsional)</Label>
              <Input
                id="deskripsi"
                value={formData.deskripsi}
                onChange={(e) => setFormData({ ...formData, deskripsi: e.target.value })}
                placeholder="Keterangan tambahan"
              />
            </div>
            <div>
              <Label htmlFor="nominal">Nominal (Rp)</Label>
              <Input
                id="nominal"
                type="text"
                value={displayNominal()}
                onChange={handleNominalChange}
                placeholder="3000000"
              />
            </div>
            <div>
              <Label htmlFor="periode">Periode</Label>
              <Select
                value={formData.periode}
                onValueChange={(value) => setFormData({ ...formData, periode: value })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="Bulanan">Bulanan</SelectItem>
                  <SelectItem value="Tahunan">Tahunan</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="flex items-center space-x-2">
              <Switch
                id="aktif"
                checked={formData.aktif}
                onCheckedChange={(checked) => setFormData({ ...formData, aktif: checked })}
              />
              <Label htmlFor="aktif">Status Aktif (untuk generate otomatis)</Label>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setOpenForm(false)}>
              Batal
            </Button>
            <Button onClick={handleSave}>Simpan</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* DELETE CONFIRMATION */}
      <AlertDialog open={openDelete} onOpenChange={setOpenDelete}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus Biaya Rutin</AlertDialogTitle>
            <AlertDialogDescription>
              Apakah Anda yakin ingin menghapus biaya rutin ini? Data yang sudah dihapus
              tidak dapat dikembalikan.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Batal</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDelete}
              className="bg-red-500 hover:bg-red-600"
            >
              Hapus
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* GENERATE CONFIRMATION */}
      <AlertDialog open={openGenerate} onOpenChange={setOpenGenerate}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Generate Biaya Bulanan</AlertDialogTitle>
            <AlertDialogDescription>
              Sistem akan membuat transaksi pengeluaran untuk semua biaya rutin yang aktif.
              Pastikan data biaya rutin sudah benar sebelum melanjutkan.
              <br />
              <br />
              {generateResult && (
                <div className="mt-4 p-3 bg-green-50 dark:bg-green-900/20 rounded border border-green-200 dark:border-green-800">
                  <p className="font-medium text-green-800 dark:text-green-300">
                    ✓ Berhasil generate {generateResult.generated_count} transaksi
                  </p>
                  <ul className="mt-2 text-sm space-y-1">
                    {generateResult.transactions?.map((tx, idx) => (
                      <li key={idx} className="text-green-700 dark:text-green-400">
                        • {tx.nama}: {formatRupiah(tx.nominal)}
                      </li>
                    ))}
                  </ul>
                </div>
              )}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel onClick={() => setGenerateResult(null)}>
              Tutup
            </AlertDialogCancel>
            {!generateResult && (
              <AlertDialogAction
                onClick={handleGenerate}
                className="bg-green-500 hover:bg-green-600"
              >
                Generate Sekarang
              </AlertDialogAction>
            )}
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* UPLOAD IMAGE DIALOG */}
      <Dialog open={openUploadImage} onOpenChange={setOpenUploadImage}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>Upload Foto Nota</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            {/* Upload Input */}
            <div className="border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-lg p-6">
              <input
                id="image-upload"
                type="file"
                multiple
                accept="image/*"
                capture="environment"
                onChange={handleImageChange}
                className="hidden"
              />
              <label
                htmlFor="image-upload"
                className="flex flex-col items-center justify-center cursor-pointer gap-2"
              >
                <ImagePlus className="h-8 w-8 text-blue-500" />
                <span className="text-sm font-medium text-gray-700 dark:text-gray-300">
                  Klik untuk upload atau ambil foto
                </span>
                <span className="text-xs text-gray-500 dark:text-gray-400">
                  Bisa upload multiple foto sekaligus
                </span>
              </label>
            </div>

            {/* Image Preview Grid */}
            {imagePreview.length > 0 && (
              <div>
                <label className="text-sm font-medium mb-2 block">
                  Foto yang akan diupload ({imagePreview.length})
                </label>
                <div className="grid grid-cols-3 gap-3">
                  {imagePreview.map((img) => (
                    <div
                      key={img.id}
                      className="relative aspect-square rounded-lg overflow-hidden bg-gray-100 dark:bg-gray-800"
                    >
                      <img
                        src={img.preview}
                        alt="preview"
                        className="w-full h-full object-cover"
                      />
                      <button
                        onClick={() => removeImagePreview(img.id)}
                        className="absolute top-1 right-1 bg-red-500 text-white rounded-full p-1 hover:bg-red-600"
                      >
                        <X className="h-4 w-4" />
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => {
                setOpenUploadImage(false);
                setImagePreview([]);
              }}
            >
              Batal
            </Button>
            <Button
              onClick={handleUploadImages}
              disabled={imagePreview.length === 0 || uploadingImages.length > 0}
              className="bg-blue-500 hover:bg-blue-600"
            >
              {uploadingImages.length > 0 ? (
                <>
                  <span className="animate-spin mr-2">⏳</span>
                  Uploading...
                </>
              ) : (
                <>Upload {imagePreview.length} Foto</>
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* IMAGE GALLERY MODAL */}
      <Dialog open={openGalleryModal} onOpenChange={setOpenGalleryModal}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Galeri Foto</DialogTitle>
          </DialogHeader>

          {galleryImages.length > 0 && (
            <div className="space-y-4">
              {/* Main Image Display */}
              <div className="relative bg-gray-100 dark:bg-gray-800 rounded-lg overflow-hidden flex items-center justify-center" style={{ minHeight: '280px', maxHeight: '350px' }}>
                {galleryImageDataUrls[galleryImages[selectedGalleryIndex].id] ? (
                  <img
                    src={galleryImageDataUrls[galleryImages[selectedGalleryIndex].id]}
                    alt="Gallery"
                    className="max-w-full max-h-full object-contain"
                  />
                ) : (
                  <div className="text-gray-400 dark:text-gray-500 text-center">
                    <div className="text-4xl mb-2">📷</div>
                    <p>Loading image...</p>
                  </div>
                )}
              </div>

              {/* Image Info */}
              <div className="text-center space-y-2">
                <div>
                  <p className="font-medium text-base">{galleryImages[selectedGalleryIndex].file_name}</p>
                  <p className="text-xs text-gray-600 dark:text-gray-400">
                    Foto {selectedGalleryIndex + 1} dari {galleryImages.length} • {(galleryImages[selectedGalleryIndex].file_size / 1024 / 1024).toFixed(2)} MB
                  </p>
                </div>
                {canDelete("biaya-rutin") && (
                  <Button
                    variant="destructive"
                    size="sm"
                    onClick={() => handleDeleteImage(galleryImages[selectedGalleryIndex].id)}
                    className="w-full h-8 text-xs"
                  >
                    <Trash2 className="h-3 w-3 mr-1" />
                    Hapus
                  </Button>
                )}
              </div>

              {/* Thumbnail Grid */}
              {galleryImages.length > 1 && (
                <div>
                  <label className="text-sm font-medium mb-2 block">Foto lainnya</label>
                  <div className="grid grid-cols-4 gap-2">
                    {galleryImages.map((img, idx) => (
                      <div
                        key={img.id}
                        className="relative"
                      >
                        <button
                          onClick={() => setSelectedGalleryIndex(idx)}
                          className={`relative overflow-hidden rounded border-2 transition h-16 w-full ${
                            selectedGalleryIndex === idx
                              ? 'border-blue-500 ring-2 ring-blue-300'
                              : 'border-gray-300 dark:border-gray-600 hover:border-blue-400'
                          }`}
                        >
                          {galleryImageDataUrls[img.id] ? (
                            <img
                              src={galleryImageDataUrls[img.id]}
                              alt="Thumbnail"
                              className="w-full h-full object-cover"
                            />
                          ) : (
                            <div className="w-full h-full bg-gray-300 dark:bg-gray-600 flex items-center justify-center text-xs text-gray-500">
                              Loading...
                            </div>
                          )}
                        </button>
                        {canDelete("biaya-rutin") && (
                          <button
                            onClick={() => handleDeleteImage(img.id)}
                            className="absolute -top-2 -right-2 bg-red-500 hover:bg-red-600 text-white rounded-full p-1 transition"
                            title="Hapus foto"
                          >
                            <Trash2 className="h-3 w-3" />
                          </button>
                        )}
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Navigation */}
              {galleryImages.length > 1 && (
                <div className="flex justify-between items-center gap-2">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setSelectedGalleryIndex(Math.max(0, selectedGalleryIndex - 1))}
                    disabled={selectedGalleryIndex === 0}
                    className="text-xs"
                  >
                    ← Prev
                  </Button>
                  <span className="text-xs text-gray-600 dark:text-gray-400">
                    {selectedGalleryIndex + 1} / {galleryImages.length}
                  </span>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setSelectedGalleryIndex(Math.min(galleryImages.length - 1, selectedGalleryIndex + 1))}
                    disabled={selectedGalleryIndex === galleryImages.length - 1}
                    className="text-xs"
                  >
                    Next →
                  </Button>
                </div>
              )}
            </div>
          )}

          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setOpenGalleryModal(false)}
            >
              Tutup
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* DELETE IMAGE ALERT DIALOG */}
      <AlertDialog open={openDeleteImage} onOpenChange={setOpenDeleteImage}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus Foto</AlertDialogTitle>
            <AlertDialogDescription>
              Apakah Anda yakin ingin menghapus foto ini? Data yang sudah dihapus
              tidak dapat dikembalikan.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Batal</AlertDialogCancel>
            <AlertDialogAction
              onClick={confirmDeleteImage}
              className="bg-red-500 hover:bg-red-600"
            >
              Hapus
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}
