import { useEffect, useState } from "react";

import { API_BASE_URL } from '@/config/api';
import { useNavigate } from "react-router-dom";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "@/components/ui/sonner";
import { useAuth } from "@/contexts/AuthContext";

export default function RekapIPL() {
  const [summary, setSummary] = useState(null);
  const [recap, setRecap] = useState([]);
  const [advanceBalances, setAdvanceBalances] = useState({});
  const [loading, setLoading] = useState(false);
  const [search, setSearch] = useState("");
  const [filterStatus, setFilterStatus] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;
  const { token } = useAuth();
  const navigate = useNavigate();

  const handleNavigateToRumah = (blokRumah, rumahId) => {
    navigate("/rumah", { state: { searchBlok: blokRumah, rumah_id: rumahId } });
  };

  const loadSummary = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/ipl/recap/summary`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await res.json();
      setSummary(data);
    } catch (err) {
      console.error("Error:", err);
    }
  };

  const loadRecap = async () => {
    setLoading(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/ipl/bills`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const billsData = await res.json();
      
      // Group bills by rumah_id to create recap
      const recapMap = {};
      billsData.forEach((bill) => {
        if (!recapMap[bill.rumah_id]) {
          recapMap[bill.rumah_id] = {
            rumah_id: bill.rumah_id,
            pemilik_sah: bill.pemilik_sah,
            blok_no: bill.blok_no,
            total_tagihan: 0,
            total_lunas: 0,
            belum_bayar: 0,
            status_pembayaran: "Belum Bayar",
          };
        }
        const item = recapMap[bill.rumah_id];
        item.total_tagihan += bill.jumlah || 0;
        if (bill.status === "Lunas") {
          item.total_lunas += bill.jumlah || 0;
        } else {
          item.belum_bayar += bill.jumlah || 0;
        }
        // Update status berdasarkan belum_bayar
        item.status_pembayaran = item.belum_bayar === 0 ? "Lunas" : "Belum Bayar";
      });
      
      setRecap(Object.values(recapMap));
      
      // Load advance balances for each rumah
      const balances = {};
      for (const item of Object.values(recapMap)) {
        try {
          const balRes = await fetch(`${API_BASE_URL}/api/ipl/advance-balance/${item.rumah_id}`, {
            headers: { Authorization: `Bearer ${token}` },
          });
          const balData = await balRes.json();
          balances[item.rumah_id] = balData.saldo || 0;
        } catch (err) {
          balances[item.rumah_id] = 0;
        }
      }
      setAdvanceBalances(balances);
    } catch (err) {
      console.error("Error:", err);
      toast.error("Gagal memuat rekap");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadSummary();
    loadRecap();
  }, []);

  // Filter logic
  const filteredRecap = recap.filter((r) => {
    const matchSearch =
      r.pemilik_sah.toLowerCase().includes(search.toLowerCase()) ||
      r.blok_no.toLowerCase().includes(search.toLowerCase());

    let matchStatus = true;
    if (filterStatus) {
      if (filterStatus === "Lunas") {
        matchStatus = r.status_pembayaran === "Lunas";
      } else if (filterStatus === "Belum") {
        matchStatus = r.status_pembayaran.startsWith("Belum");
      }
    }

    return matchSearch && matchStatus;
  });

  const formatRupiah = (val) => {
    return new Intl.NumberFormat("id-ID", {
      style: "currency",
      currency: "IDR",
      minimumFractionDigits: 0,
    }).format(val);
  };

  return (
    <div className="space-y-6">
      {/* SUMMARY STATS */}
      {summary && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="bg-white dark:bg-gray-900 p-6 rounded-lg border dark:border-gray-700 shadow-sm">
            <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Total Tagihan</p>
            <p className="text-2xl font-bold text-blue-600 dark:text-blue-400 mt-2">
              {formatRupiah(summary.total_tagihan)}
            </p>
          </div>

          <div className="bg-white dark:bg-gray-900 p-6 rounded-lg border dark:border-gray-700 shadow-sm">
            <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Total Lunas</p>
            <p className="text-2xl font-bold text-green-600 dark:text-green-400 mt-2">
              {formatRupiah(summary.total_lunas)}
            </p>
          </div>

          <div className="bg-white dark:bg-gray-900 p-6 rounded-lg border dark:border-gray-700 shadow-sm">
            <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Belum Bayar</p>
            <p className="text-2xl font-bold text-red-600 dark:text-red-400 mt-2">
              {formatRupiah(summary.total_belum)}
            </p>
          </div>

          <div className="bg-white dark:bg-gray-900 p-6 rounded-lg border dark:border-gray-700 shadow-sm">
            <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Persentase Bayar</p>
            <p className="text-2xl font-bold text-purple-600 dark:text-purple-400 mt-2">
              {summary.persentase_bayar.toFixed(1)}%
            </p>
          </div>
        </div>
      )}

      {/* TABLE RECAP */}
      <div className="space-y-4">
        {/* Search and Filter */}
        <div className="grid grid-cols-3 gap-3">
          <div className="col-span-2">
            <Input
              placeholder="Cari nama warga atau blok rumah..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="dark:bg-gray-800 dark:text-gray-100 dark:border-gray-700"
            />
          </div>
          <div className="flex gap-2">
            <select
              value={filterStatus}
              onChange={(e) => setFilterStatus(e.target.value)}
              className="flex-1 p-2 border rounded dark:bg-gray-800 dark:text-gray-100 dark:border-gray-700 text-sm"
            >
              <option value="">Semua Status</option>
              <option value="Lunas">Lunas</option>
              <option value="Belum">Belum Bayar</option>
            </select>
            <Button
              onClick={() => {
                setSearch("");
                setFilterStatus("");
              }}
              className="bg-gray-400 hover:bg-gray-500 text-white text-sm"
            >
              Reset
            </Button>
          </div>
        </div>

        {/* Pagination Info */}
        <div className="flex justify-between items-center text-sm text-gray-600 dark:text-gray-400">
          <span>Total: {filteredRecap.length} warga</span>
          <span>
            Halaman {currentPage} dari {Math.ceil(filteredRecap.length / itemsPerPage) || 1}
          </span>
        </div>

        <div className="bg-white dark:bg-gray-900 rounded-lg border dark:border-gray-700 overflow-hidden">
          <Table>
            <TableHeader className="bg-gray-50 dark:bg-gray-800">
              <TableRow>
                <TableHead>Warga</TableHead>
                <TableHead>Blok</TableHead>
                <TableHead className="text-right">Total Tagihan</TableHead>
                <TableHead className="text-right">Sudah Lunas</TableHead>
                <TableHead className="text-right">Belum Bayar</TableHead>
                <TableHead className="text-right">Saldo Dimuka</TableHead>
                <TableHead>Status</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {loading ? (
                <TableRow>
                  <TableCell colSpan="7" className="text-center py-4">
                    Loading...
                  </TableCell>
                </TableRow>
              ) : filteredRecap.length === 0 ? (
                <TableRow>
                  <TableCell colSpan="7" className="text-center py-4 text-gray-500 dark:text-gray-400">
                    Tidak ada data
                  </TableCell>
                </TableRow>
              ) : (
                filteredRecap
                  .slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage)
                  .map((r) => (
                <TableRow key={r.rumah_id} className="dark:border-gray-700">
                  <TableCell className="font-semibold dark:text-gray-200">
                    <button
                      onClick={() => navigate("/warga", { state: { searchName: r.pemilik_sah } })}
                      className="text-blue-600 dark:text-blue-400 hover:underline cursor-pointer"
                    >
                      {r.pemilik_sah}
                    </button>
                  </TableCell>
                  <TableCell className="text-gray-600 dark:text-gray-400">
                    <button
                      onClick={() => handleNavigateToRumah(r.blok_no, r.rumah_id)}
                      className="text-blue-600 dark:text-blue-400 hover:underline cursor-pointer"
                    >
                      {r.blok_no}
                    </button>
                  </TableCell>
                  <TableCell className="text-right font-semibold dark:text-gray-200">
                    {formatRupiah(r.total_tagihan)}
                  </TableCell>
                  <TableCell className="text-right text-green-600 dark:text-green-400 font-semibold">
                    {formatRupiah(r.total_lunas)}
                  </TableCell>
                  <TableCell className="text-right text-red-600 dark:text-red-400 font-semibold">
                    {formatRupiah(r.belum_bayar)}
                  </TableCell>
                  <TableCell className="text-right">
                    {advanceBalances[r.rumah_id] > 0 ? (
                      <span className="px-2 py-1 rounded text-xs font-semibold bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200">
                        {formatRupiah(advanceBalances[r.rumah_id])}
                      </span>
                    ) : (
                      <span className="text-gray-400 text-sm">-</span>
                    )}
                  </TableCell>
                  <TableCell>
                    <span
                      className={`px-2 py-1 rounded text-xs font-semibold ${
                        r.belum_bayar === 0
                          ? "bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200"
                          : "bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200"
                      }`}
                    >
                      {r.status_pembayaran}
                    </span>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
        </div>

        {/* Pagination Buttons */}
        {filteredRecap.length > itemsPerPage && (
          <div className="flex justify-between items-center gap-2">
            <Button
              onClick={() => setCurrentPage(Math.max(1, currentPage - 1))}
              disabled={currentPage === 1}
              className="bg-gray-500 hover:bg-gray-600 text-white disabled:opacity-50"
            >
              ← Sebelumnya
            </Button>

            <div className="flex gap-1">
              {Array.from({ length: Math.ceil(filteredRecap.length / itemsPerPage) }).map((_, i) => (
                <Button
                  key={i + 1}
                  onClick={() => setCurrentPage(i + 1)}
                  className={
                    currentPage === i + 1
                      ? "bg-blue-600 hover:bg-blue-700 text-white"
                      : "bg-gray-400 hover:bg-gray-500 text-white"
                  }
                >
                  {i + 1}
                </Button>
              ))}
            </div>

            <Button
              onClick={() =>
                setCurrentPage(
                  Math.min(Math.ceil(filteredRecap.length / itemsPerPage), currentPage + 1)
                )
              }
              disabled={currentPage === Math.ceil(filteredRecap.length / itemsPerPage)}
              className="bg-gray-500 hover:bg-gray-600 text-white disabled:opacity-50"
            >
              Selanjutnya →
            </Button>
          </div>
        )}
      </div>
    </div>
  );
}
