// Helper function to build API URL
export const buildApiUrl = (path) => {
  if (path.startsWith('/')) {
    return `${API_BASE_URL}${path}`;
  }
  return `${API_BASE_URL}/${path}`;
};

export default {
  API_BASE_URL,
  WHATSAPP_BASE_URL,
  API_ENDPOINTS,
  buildApiUrl,
};
