import React, { useState, useEffect } from 'react';
import { API_BASE_URL } from '../config/api';
import { Link, useLocation } from 'react-router-dom';
import {
  LayoutDashboard,
  MessageCircle,
  Package,
  Receipt,
  Settings,
  UserCog,
  Users,
  Wallet,
  Wrench,
  Trees,
  Briefcase,
  ChevronRight,
  HelpCircle,
  X,
  DollarSign,
  Lock,
  Shield,
  FileText,
  Banknote,
  List,
  CheckCircle,
  BarChart3,
  Home,
  Activity,
  Trash2
} from 'lucide-react';
import { cn } from '../lib/utils';
import { useSidebar } from '../contexts/SidebarContext';
import { useAuth } from '../contexts/AuthContext';

const iconMap = {
  LayoutDashboard,
  MessageCircle,
  Package,
  Receipt,
  Settings,
  UserCog,
  Users,
  Wallet,
  Wrench,
  Trees,
  Briefcase,
  HelpCircle,
  DollarSign,
  Lock,
  Shield,
  FileText,
  Banknote,
  List,
  CheckCircle,
  BarChart3,
  Home,
  Activity,
  Trash2
};

/**
 * Get all menu items structure with role-based filtering
 */
const getAllMenuItems = (role) => {
  return [
    { id: 'dashboard', label: 'Dasbor', icon: 'LayoutDashboard', path: '/', color: 'text-cyan-500' },
    {
      id: 'users-menu',
      label: 'Pengguna',
      icon: 'Users',
      color: 'text-blue-500',
      hasSubmenu: true,
      submenu: [
        { id: 'users-list', label: 'Daftar Pengguna', path: '/users', icon: 'Users' },
        { id: 'user-permissions', label: 'Hak Akses Pengguna', path: '/user-permissions', icon: 'Lock' },
        { id: 'management-roles', label: 'Manajemen Role', path: '/roles', icon: 'Shield' },
      ]
    },
    {
      id: 'Kepengurusan',
      label: 'Kepengurusan',
      icon: 'UserCog',
      path: '/management',
      hasSubmenu: true,
      submenu: [
        { id: 'pengurus', label: 'Pengurus', path: '/management', icon: 'Users' },
        { id: 'rekening', label: 'Rekening Penerima', path: '/rekening', icon: 'Wallet' },
        { id: 'surat', label: 'Surat', path: '/surat', icon: 'FileText' },
      ]
    },
    {
      id: 'residents',
      label: 'Penghuni',
      icon: 'Users',
      path: '/residents',
      hasSubmenu: true,
      submenu: [
        { id: 'warga', label: 'Warga', path: '/warga', icon: 'Users' },
        { id: 'rumah', label: 'Rumah', path: '/rumah', icon: 'Home' },
      ]
    },
    { id: 'karyawan', label: 'Karyawan', icon: 'Briefcase', path: '/karyawan', color: 'text-purple-500' },
    {
      id: 'finance',
      label: 'Keuangan',
      icon: 'DollarSign',
      color: 'text-emerald-500',
      hasSubmenu: true,
      submenu: [
        { id: 'kas', label: 'Kas', path: '/finance', icon: 'DollarSign' },
        { id: 'biaya-rutin', label: 'Biaya Rutin', path: '/biaya/rutin', icon: 'Receipt' },
        // { id: 'thr', label: 'THR', path: '/biaya/thr', icon: 'Gift' },
        { id: 'ipl', label: 'Iuran IPL', path: '/ipl', icon: 'FileText' },
        // { id: 'dana', label: 'Dana & Kas', path: '/dana', icon: 'Banknote' },
        { id: 'budget', label: 'Budget', path: '/budget', icon: 'Wallet' },
        { id: 'kasbon', label: 'Kasbon', path: '/kasbon', icon: 'Banknote' },
        { id: 'laporan', label: 'Laporan', path: '/laporan', icon: 'FileText' },
      ]
    },
    { id: 'whatsapp', label: 'Integrasi Whatsapp', icon: 'MessageCircle', path: '/whatsapp', color: 'text-green-500' },
    { id: 'aktivitas-log', label: 'Log Aktivitas', icon: 'Activity', path: '/aktivitas-log', color: 'text-indigo-500' },
    // { id: 'data-management', label: 'Kelola Data', icon: 'Trash2', path: '/data-management', color: 'text-red-500' },
    {
      id: 'configuration',
      label: 'Konfigurasi',
      icon: 'Settings',
      color: 'text-gray-600',
      hasSubmenu: true,
      submenu: [
        { id: 'kategori-biaya', label: 'Kategori Biaya', path: '/biaya/kategori', icon: 'Package' },
        { id: 'tarif-ipl', label: 'Tarif IPL', path: '/tarif-ipl', icon: 'Settings' },
      ]
    },
  ];
};

/**
 * Filter menu items based on database role permissions
 */
const getMenuItems = (role, dbPermissions) => {
  const allMenus = getAllMenuItems(role);

  return allMenus.filter(menu => {
    // Map menu IDs to permission keys
    const permissionKey = menu.id === 'users-menu' ? 'users-list' :
      menu.id === 'Kepengurusan' ? 'pengurus' :
        menu.id === 'residents' ? 'warga' :
          menu.id;

    // Check if role has read permission from database
    // Default to true (show menu) if no permission entry exists yet
    const permission = dbPermissions[permissionKey];
    const canRead = permission?.read !== false;  // Show unless explicitly set to false

    return canRead;
  }).map(menu => {
    // Filter submenus if they exist
    if (menu.hasSubmenu && menu.submenu) {
      return {
        ...menu,
        submenu: menu.submenu.filter(submenu => {
          const permission = dbPermissions[submenu.id];
          return permission?.read !== false;  // Show unless explicitly set to false
        })
      };
    }
    return menu;
  });
};

const Sidebar = () => {
  const location = useLocation();
  const { user, token } = useAuth();
  const { isOpen, isMobile, closeSidebar } = useSidebar();
  const [filterText, setFilterText] = useState('');
  const [expandedMenus, setExpandedMenus] = useState({});
  const [dbPermissions, setDbPermissions] = useState({});
  const [loadingPerms, setLoadingPerms] = useState(true);

  // Load permissions from database
  useEffect(() => {
    const loadPermissions = async () => {
      if (!user?.role || !token) {
        setDbPermissions({});
        setLoadingPerms(false);
        return;
      }

      try {
        const res = await fetch(`${API_BASE_URL}/api/role-permissions/${user.role}`, {
          headers: { Authorization: `Bearer ${token}` }
        });

        if (res.ok) {
          const data = await res.json();
          // Extract permissions object from response
          const perms = data.permissions || {};
          console.log('Loaded permissions for', user.role, ':', perms);
          setDbPermissions(perms);
        } else {
          setDbPermissions({});
        }
      } catch (err) {
        console.error('Failed to load role permissions:', err);
        setDbPermissions({});
      } finally {
        setLoadingPerms(false);
      }
    };

    loadPermissions();

    // Set up auto-refresh every 2 seconds to pick up permission changes from matrix page
    const interval = setInterval(loadPermissions, 2000);

    return () => clearInterval(interval);
  }, [user?.role, token]);

  const menuItems = getMenuItems(user?.role || 'admin', dbPermissions);

  // Filter menu items based on filter text
  const filteredMenuItems = menuItems.filter(item =>
    item.label.toLowerCase().includes(filterText.toLowerCase())
  );

  const toggleSubmenu = (itemId) => {
    setExpandedMenus(prev => ({
      ...prev,
      [itemId]: !prev[itemId]
    }));
  };

  return (
    <>
      {/* Overlay for mobile */}
      {isMobile && isOpen && (
        <div
          className="fixed inset-0 bg-black/50 z-40 lg:hidden"
          onClick={closeSidebar}
        />
      )}

      {/* Sidebar */}
      <aside
        className={cn(
          "fixed lg:static inset-y-0 left-0 z-50 w-64 bg-white dark:bg-gray-900 border-r border-gray-200 dark:border-gray-800 h-screen overflow-y-auto flex flex-col transition-transform duration-300 ease-in-out",
          !isOpen && isMobile && "-translate-x-full",
          isOpen && "translate-x-0"
        )}
      >
        {/* Logo */}
        <div className="p-6 border-b border-gray-200 dark:border-gray-800">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <img
                src={require('../assets/images/logo-perum_botanika.png')}
                alt="Logo"
                className="w-20 h-20 object-contain"
              />
              <span className="text-xl font-bold text-gray-800 dark:text-white">
                KBBS
              </span>
            </div>
            {/* Close button for mobile */}
            {isMobile && (
              <button
                onClick={closeSidebar}
                className="lg:hidden p-1.5 rounded-md hover:bg-gray-100 dark:hover:bg-gray-800"
              >
                <X className="h-5 w-5 text-gray-600 dark:text-gray-400" />
              </button>
            )}
          </div>
        </div>

        {/* Filter */}
        <div className="p-4 border-b border-gray-200 dark:border-gray-800">
          <input
            type="text"
            placeholder="Filter"
            value={filterText}
            onChange={(e) => setFilterText(e.target.value)}
            className="w-full px-3 py-2 text-sm border border-gray-200 dark:border-gray-700 rounded-md bg-white dark:bg-gray-800 focus:outline-none focus:ring-1 focus:ring-cyan-500 text-gray-700 dark:text-gray-200"
          />
        </div>

        {/* Menu Items */}
        <nav className="flex-1 p-4 space-y-1">
          {filteredMenuItems.length > 0 ? (
            filteredMenuItems.map((item) => {
              const Icon = iconMap[item.icon];
              const isActive = location.pathname === item.path;
              const isExpanded = expandedMenus[item.id];
              const hasActiveSubmenu = item.submenu?.some(sub => location.pathname === sub.path);

              if (item.hasSubmenu && item.submenu) {
                return (
                  <div key={item.id}>
                    <button
                      onClick={() => toggleSubmenu(item.id)}
                      className={cn(
                        "w-full flex items-center gap-3 px-3 py-2.5 rounded-md text-sm font-medium transition-colors duration-150",
                        isActive || hasActiveSubmenu
                          ? "bg-cyan-50 dark:bg-cyan-900/20 text-cyan-600 dark:text-cyan-400"
                          : "text-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-800"
                      )}
                    >
                      <Icon className={cn("h-5 w-5 flex-shrink-0", isActive || hasActiveSubmenu ? "text-cyan-500" : "text-gray-500 dark:text-gray-400")} />
                      <span className="flex-1 text-left">{item.label}</span>
                      <ChevronRight className={cn("h-4 w-4 text-gray-400 flex-shrink-0 transition-transform", isExpanded && "rotate-90")} />
                    </button>
                    {isExpanded && (
                      <div className="ml-2 mt-1 space-y-1 border-l border-gray-200 dark:border-gray-700 pl-3">
                        {item.submenu.map(subitem => {
                          const isSubActive = location.pathname === subitem.path;
                          const SubIcon = subitem.icon ? iconMap[subitem.icon] : null;
                          return (
                            <Link
                              key={subitem.id}
                              to={subitem.path}
                              onClick={closeSidebar}
                              className={cn(
                                "flex items-center gap-3 px-3 py-2 rounded-md text-sm font-medium transition-colors duration-150",
                                isSubActive
                                  ? "bg-cyan-50 dark:bg-cyan-900/20 text-cyan-600 dark:text-cyan-400"
                                  : "text-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-800"
                              )}
                            >
                              {SubIcon ? (
                                <SubIcon className="h-4 w-4 flex-shrink-0" />
                              ) : (
                                <span className="w-4 h-4 flex-shrink-0" />
                              )}
                              <span className="flex-1">{subitem.label}</span>
                            </Link>
                          );
                        })}
                      </div>
                    )}
                  </div>
                );
              }

              return (
                <Link
                  key={item.id}
                  to={item.path}
                  onClick={closeSidebar}
                  className={cn(
                    "flex items-center gap-3 px-3 py-2.5 rounded-md text-sm font-medium transition-colors duration-150",
                    isActive
                      ? "bg-cyan-50 dark:bg-cyan-900/20 text-cyan-600 dark:text-cyan-400"
                      : "text-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-800"
                  )}
                >
                  <Icon className={cn("h-5 w-5 flex-shrink-0", isActive ? "text-cyan-500" : "text-gray-500 dark:text-gray-400")} />
                  <span className="flex-1">{item.label}</span>
                </Link>
              );
            })
          ) : (
            <div className="text-center py-8 text-sm text-gray-500 dark:text-gray-400">
              Tidak ada menu yang cocok
            </div>
          )}
        </nav>

        {/* Footer */}
        <div className="p-4 border-t border-gray-200 dark:border-gray-800 text-center">
          <p className="text-sm font-bold text-yellow-600 dark:text-yellow-400">KELUARGA BESAR</p>
          <p className="text-xs font-bold text-yellow-600 dark:text-yellow-400 mt-1">BOTANIKA SRIWIDARI</p>
          <p className="text-xs font-bold text-yellow-600 dark:text-yellow-400">KOTA SUKABUMI</p>
          <p className="text-xs text-gray-500 dark:text-gray-400 mt-3">
            Developed by nsudiana © {new Date().getFullYear()} v1.0.4
          </p>
        </div>
      </aside>
    </>
  );
};

export default Sidebar;